    pub fn encode_batch(&self, texts: &[&str]) -> Result<EncodedBatch, EmbedError> {
        if texts.is_empty() {
            return Ok(EncodedBatch {
                input_ids: Vec::new(),
                attention_mask: Vec::new(),
                batch_size: 0,
                seq_len: 0,
            });
        }
        let inputs: Vec<String> = texts.iter().map(|s| s.to_string()).collect();
        let encodings = self
            .inner
            .encode_batch(inputs, true)
            .map_err(|e| EmbedError::Backend(format!("tokenizer encode_batch: {e}")))?;

        let batch_size = encodings.len();
        let seq_len = encodings
            .iter()
            .map(|e| e.get_ids().len())
            .max()
            .unwrap_or(0);

        let mut input_ids = Vec::with_capacity(batch_size * seq_len);
        let mut attention_mask = Vec::with_capacity(batch_size * seq_len);
        for enc in &encodings {
            let ids = enc.get_ids();
            let mask = enc.get_attention_mask();
            // BatchLongest already padded to seq_len, so ids.len() == seq_len.
            for &id in ids {
                input_ids.push(id as i64);
            }
            for &m in mask {
                attention_mask.push(m as i64);
            }
        }
        Ok(EncodedBatch {
            input_ids,
            attention_mask,
            batch_size,
            seq_len,
        })
    }
}

    fn forward_sentence_batch(&self, texts: &[&str]) -> Result<Option<Tensor<2>>, EmbedError> {
        let model = self.model.as_ref().ok_or(EmbedError::ModelNotLoaded)?;
        let tokenizer = self.tokenizer.as_ref().ok_or(EmbedError::ModelNotLoaded)?;

        if texts.is_empty() {
            return Ok(None);
        }

        let batch = tokenizer.encode_batch(texts)?;
        let input_ids: Tensor<2, Int> = Tensor::from_data(
            TensorData::new(batch.input_ids, [batch.batch_size, batch.seq_len]),
            &self.device,
        );

        Ok(Some(model.forward_sentence(
            input_ids,
            self.pooling,
            self.l2_normalize,
        )))
    }
}

    pub fn forward(&self, hidden: Tensor<3>) -> Tensor<3> {
        let [batch, seq_len, hidden_size] = hidden.dims();
        let num_heads = self.num_heads;
        let head_dim = self.head_dim;

        let q = self.query.forward(hidden.clone());
        let k = self.key.forward(hidden.clone());
        let v = self.value.forward(hidden);

        // Reshape for multi-head: [B, S, H] -> [B, S, num_heads, head_dim] ->
        // [B, num_heads, S, head_dim]
        let q = q
            .reshape([batch, seq_len, num_heads, head_dim])
            .swap_dims(1, 2);
        let k = k
            .reshape([batch, seq_len, num_heads, head_dim])
            .swap_dims(1, 2);
        let v = v
            .reshape([batch, seq_len, num_heads, head_dim])
            .swap_dims(1, 2);

        // Scaled-dot-product: Q @ K^T / sqrt(d_k)
        let scale = (head_dim as f32).sqrt();
        let scores = q.matmul(k.swap_dims(2, 3)).div_scalar(scale);
        let attn = softmax(scores, 3);

        // Apply attention to V: [B, num_heads, S, head_dim]
        let context = attn.matmul(v);

        // Reshape back: [B, num_heads, S, head_dim] -> [B, S, num_heads, head_dim]
        // -> [B, S, hidden_size]
        context
            .swap_dims(1, 2)
            .reshape([batch, seq_len, hidden_size])
    }
}

    pub fn forward_sentence(
        &self,
        input_ids: Tensor<2, Int>,
        pooling: Pooling,
        l2_normalize: bool,
    ) -> Tensor<2> {
        let token_repr = self.forward_tokens(input_ids);
        let pooled = match pooling {
            Pooling::Mean => mean_pool(token_repr),
            Pooling::Cls => cls_pool(token_repr),
        };
        if l2_normalize {
            l2_normalize_rows(pooled)
        } else {
            pooled
        }
    }
}

/// Mean-pool along the sequence (dim 1). `[B, S, H]` → `[B, H]`.
fn mean_pool(token_repr: Tensor<3>) -> Tensor<2> {
    let [batch, _, hidden] = token_repr.dims();
    token_repr.mean_dim(1).reshape([batch, hidden])
}

/// Take the first token's representation. `[B, S, H]` → `[B, H]`.
fn cls_pool(token_repr: Tensor<3>) -> Tensor<2> {
    let [batch, _, hidden] = token_repr.dims();
    token_repr
        .slice([0..batch, 0..1, 0..hidden])
        .reshape([batch, hidden])
}

/// L2-normalise along the last dim. `[B, H]` rows → unit norm.
fn l2_normalize_rows(rows: Tensor<2>) -> Tensor<2> {
    let squared = rows.clone() * rows.clone();
    let sum = squared.sum_dim(1);
    let norm = sum.sqrt().clamp_min(f32::EPSILON);
    rows / norm
}

pub fn cosine_top_k(
    queries: &[Vec<f32>],
    corpus: &[Vec<f32>],
    k: usize,
    device: &Device,
) -> Vec<Vec<(usize, f32)>> {
    let q = queries.len();
    let n = corpus.len();
    if q == 0 {
        return Vec::new();
    }
    if n == 0 || k == 0 {
        return vec![Vec::new(); q];
    }
    let dim = corpus[0].len();
    let k = k.min(n);

    // [Q, N] cosine similarity as one matmul on unit-normalized rows.
    let qn = l2_normalize_rows(rows_to_tensor(queries, dim, device));
    let cn = l2_normalize_rows(rows_to_tensor(corpus, dim, device));
    let sim = qn.matmul(cn.swap_dims(0, 1)); // [Q, d] · [d, N] = [Q, N]
    let scores = sim
        .into_data()
        .try_to_vec::<f32>()
        .expect("similarity readback is f32");

    // Per-query top-k over the read-back row (cheap O(N) vs the matmul above).
    let mut out = Vec::with_capacity(q);
    for qi in 0..q {
        let row = &scores[qi * n..(qi + 1) * n];
        let mut scored: Vec<(usize, f32)> = row.iter().copied().enumerate().collect();
        scored.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));
        scored.truncate(k);
        out.push(scored);
    }
    out
}

/// Stack `rows` (each length `dim`) into a `[rows.len(), dim]` tensor on `B`.
fn rows_to_tensor(rows: &[Vec<f32>], dim: usize, device: &Device) -> Tensor<2> {
    let mut flat = Vec::with_capacity(rows.len() * dim);
    for row in rows {
        flat.extend_from_slice(row);
    }
    Tensor::from_data(TensorData::new(flat, [rows.len(), dim]), device)
}

/// Scale each row of a `[R, d]` tensor to unit L2 length. A zero row (norm ~0)
/// stays ~zero (the `1e-12` guard divides it by epsilon, not by zero), so its
/// cosine against anything is 0 — matching [`VectorIndex`](crate::embed::VectorIndex).
fn l2_normalize_rows(t: Tensor<2>) -> Tensor<2> {
    let sq_sum = (t.clone() * t.clone()).sum_dim(1); // [R, 1]
    let inv_norm = sq_sum.sqrt().add_scalar(1e-12).recip(); // [R, 1]
    t * inv_norm // [R, d] * [R, 1] broadcasts over the row
}

/// [`cosine_top_k`] over a [`VectorIndex`]'s entries, returning results keyed by
/// the index's own `K` (not corpus positions). The GPU path for recall / search;
/// a consumer routes to it when the index has at least [`SEARCH_GPU_MIN_ENTRIES`].
/// Cosine only.
pub fn nearest_over_index<K>(
    index: &VectorIndex<K>,
    queries: &[Vec<f32>],
    k: usize,
    device: &Device,
) -> Vec<Vec<(K, f32)>>
where
    K: Hash + Eq + Clone,
{
    let entries: Vec<(K, Vec<f32>)> = index
        .iter()
        .map(|(key, v)| (key.clone(), v.clone()))
        .collect();
    let corpus: Vec<Vec<f32>> = entries.iter().map(|(_, v)| v.clone()).collect();
    cosine_top_k(queries, &corpus, k, device)
        .into_iter()
        .map(|row| {
            row.into_iter()
                .map(|(pos, score)| (entries[pos].0.clone(), score))
                .collect()
        })
        .collect()
}

impl BertIntermediate {
    pub fn new(config: &BertConfig, device: &Device) -> Self {
        Self {
            dense: LinearConfig::new(config.hidden_size, config.intermediate_size).init(device),
        }
    }

    pub fn from_loaded(loaded: &super::loaded::LoadedBertLayer, device: &Device) -> Self {
        Self {
            dense: super::construct::linear_from_loaded(
                loaded.inter_w.clone(),
                loaded.inter_b.clone(),
                device,
            ),
        }
    }

    /// `gelu(dense(x))`. Input `[B, S, hidden]`, output `[B, S, intermediate]`.
    pub fn forward(&self, hidden: Tensor<3>) -> Tensor<3> {
        gelu(self.dense.forward(hidden))
    }
}
